// Raccoon Golf's art (port of src/kpapp/game/golf/art.py), generated by
// tools/generate_golf_assets.py into assets/golf/generated/. All art is
// original and procedural. The manifest carries the numbers that belong to the
// art (the focal length the sky was painted for, tree anchors, where Lenny's
// arms attach, the ground's colours) so they travel with the sprites.
//
// The manifest's colours are OpenCV BGR; this loader turns every one into RGB,
// so nothing downstream has to remember (AGENTS.md section 11).
//
// Nothing here touches the DOM until loadArt() is called, so game.js can
// import it under Node.

import { loadImage, loadJSON } from "../../core/gfx.js";

export const ASSET_URL = new URL("../../../assets/golf/generated/", import.meta.url);
const GENERATOR = "uv run python tools/generate_golf_assets.py";

/** [b, g, r] -> [r, g, b]. */
export const bgr = (c) => [c[2], c[1], c[0]];

/** The manifest with every BGR colour as RGB (ground and Lenny's colours). */
export function toRgb(spec) {
  const out = structuredClone(spec ?? {});
  for (const k of Object.keys(out.ground ?? {})) out.ground[k] = bgr(out.ground[k]);
  const lc = out.lenny?.colours ?? {};
  for (const k of Object.keys(lc)) lc[k] = bgr(lc[k]);
  return out;
}

/**
 * GolfArt: sky (a panorama, one full turn of yaw, stored at half size: draw it
 * scaled to manifest pano_w x pano_h, horizon at the bottom row), sea (1280
 * wide, tiles horizontally, row 0 is the horizon), haze (blended under the
 * horizon), trees {palm, round} (anchored at manifest foot), lenny (his body at
 * address, no arms), ball, gauge and gaugeFill (revealed from the bottom), and
 * the manifest with RGB colours.
 */
export class GolfArt {
  constructor(images, manifest) {
    Object.assign(this, images);
    this.manifest = toRgb(manifest);
  }
}

let cache = null;
let pending = null;

export function cachedArt() {
  return cache;
}

export async function loadArt({ reload = false } = {}) {
  if (cache && !reload) return cache;
  if (pending && !reload) return pending;
  const url = (name) => new URL(name, ASSET_URL).href;
  pending = (async () => {
    let spec;
    try {
      spec = await loadJSON(url("manifest.json"));
    } catch (err) {
      throw new Error(`Raccoon Golf art is missing (${err.message}). Run: ${GENERATOR}`);
    }
    const img = (name) => loadImage(url(name)).catch(() => {
      throw new Error(`missing assets/golf/generated/${name}. Run: ${GENERATOR}`);
    });
    const [sky, sea, haze, palm, round, lenny, ball, gauge, gaugeFill] = await Promise.all([
      img("sky.png"), img("sea.png"), img("haze.png"), img(spec.trees.palm.file), img(spec.trees.round.file),
      img(spec.lenny.file), img("ball.png"), img("gauge.png"), img("gauge_fill.png"),
    ]);
    cache = new GolfArt({ sky, sea, haze, trees: { palm, round }, lenny, ball, gauge, gaugeFill }, spec);
    return cache;
  })();
  try {
    return await pending;
  } finally {
    pending = null;
  }
}

/** Placeholder art with the real manifest's shape, for Node tests (no pixels). */
export function stubArt() {
  const sprite = (width, height) => ({ width, height });
  const grey = [200, 200, 200];
  return new GolfArt({
    sky: sprite(3141, 220), sea: sprite(1280, 560), haze: sprite(1280, 64),
    trees: { palm: sprite(16, 32), round: sprite(16, 32) }, lenny: sprite(24, 30), ball: sprite(8, 8),
    gauge: sprite(16, 100), gaugeFill: sprite(16, 100),
  }, {
    focal: 1000.0, pano_w: 6283, pano_h: 440, sun: [0.12, 330],
    trees: { palm: { foot: [8, 30], top: 0 }, round: { foot: [8, 30], top: 0 } },
    lenny: { shoulder_back: [10, 12], shoulder_front: [14, 12], arm: 8.0, club: 12.0, address_dir: 34.0,
      colours: Object.fromEntries(["fur", "sleeve", "glove", "ink", "shaft", "head", "face"].map((k) => [k, grey])) },
    gauge: { inner: [2, 2, 14, 98], full_frac: 1 / 1.15 },
    ground: Object.fromEntries(["rough", "fairway", "fairway_stripe", "green", "green_stripe", "fringe", "tee",
      "bunker", "bunker_rim", "water", "water_hi", "water_rim", "beach", "edge", "haze", "sea"].map((k) => [k, [100, 160, 90]])),
    ball_visual_radius_m: 0.075,
  });
}
